import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { parseCsv } from '../src/csv.ts';
import { cleanRow, mapHeader } from '../src/sheet/contract.ts';
import { readInbox, readSchemaVersion } from '../src/sheet/tabs.ts';

/** docs/template is generated by tools/template/make_template.py; it must read cleanly under the contract. */
const dir = join(__dirname, '../../docs/template');
const read = (f: string) => parseCsv(readFileSync(join(dir, f), 'utf8'), { keepEmpty: true });

describe('sheet template', () => {
  it('every Words header is a known column, and the example row reads without a note', () => {
    const [head, example] = read('Words.csv');
    const m = mapHeader(head!);
    expect(m.unknown).toEqual([]);
    expect(m.repeated).toEqual([]);
    const c = cleanRow(example!, m);
    expect(c.skip).toBe(false);
    expect(c.notes).toEqual([]);
  });
  it('the Inbox and Meta tabs read as the app expects', () => {
    expect(readInbox(read('Inbox.csv'))).toEqual({ ok: true, total: 0, waiting: 0, processed: 0 });
    expect(readSchemaVersion(read('Meta.csv'))).toEqual({ status: 'same' });
  });
});
